-- Phase 5: monitoring — follow-up log, due reminders and date filters. Additive only.

-- 1. The follow-up log of inquiries (Marketing) and applicants (assigned Sales). Append-only.
create table if not exists public."follow_ups" (
  "id" bigint generated by default as identity primary key,
  "followable_type" text not null,
  "followable_id" bigint not null,
  "user_id" bigint references public."users" ("id") on delete set null,
  "actor_role" text,
  "contacted_at" timestamptz not null,
  "channel" text not null,
  "outcome" text not null,
  "notes" text not null,
  "next_follow_up_at" timestamptz,
  "created_at" timestamptz not null default now(),
  constraint "follow_ups_type_check" check ("followable_type" in ('inquiry', 'applicant')),
  constraint "follow_ups_channel_check" check ("channel" in ('call', 'text', 'viber', 'email', 'in_person', 'other')),
  constraint "follow_ups_outcome_check" check ("outcome" in ('reached', 'no_answer', 'rescheduled', 'not_interested'))
);
create index if not exists "follow_ups_record_idx" on public."follow_ups" ("followable_type", "followable_id", "contacted_at");
create index if not exists "follow_ups_next_idx" on public."follow_ups" ("next_follow_up_at") where "next_follow_up_at" is not null;
alter table public."follow_ups" enable row level security;
drop trigger if exists "follow_ups_append_only" on public."follow_ups";
create trigger "follow_ups_append_only" before update on public."follow_ups"
  for each row execute function public.refuse_history_update();

-- 2. One reminder per follow-up: the row is the proof it was sent (the follow-up row is never updated).
create table if not exists public."follow_up_reminders" (
  "follow_up_id" bigint primary key references public."follow_ups" ("id") on delete cascade,
  "user_id" bigint references public."users" ("id") on delete set null,
  "notified_at" timestamptz not null default now()
);
alter table public."follow_up_reminders" enable row level security;

-- 3. Indexes for the date filters (Date Applied and Inquiry date are already indexed).
create index if not exists "applicants_approved_at_idx" on public."applicants" ("approved_at");
create index if not exists "applicants_rejected_at_idx" on public."applicants" ("rejected_at");
create index if not exists "applicants_updated_at_idx" on public."applicants" ("updated_at");
create index if not exists "applicant_stage_histories_stage_idx" on public."applicant_stage_histories" ("applicant_id", "to_stage", "changed_at");
